  ('A6300-01', '품질문제 신고서', 'A-6300', '품질 문제를 발견한 직원이 내는 신고서. 신고 내용·발견 경위를 적고 포상 심사로 이어집니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', NULL, NULL, 'templates/standard/A6300-01.xlsx'),
