  ('A7100-02', '클린신고서', 'A-7100', '윤리 위반·부정 행위를 신고하는 클린 신고서. 신고자 보호 원칙에 따라 접수됩니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '5', NULL, 'templates/standard/A7100-02.xlsx'),
  ('A8100-01', 'RISK 분석표', 'A-8100', '프로세스별 리스크를 찾아 발생 가능성·심각도로 평가하고 대응책을 적는 분석표(IATF 6.1). 연 1회 이상 갱신합니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '6', NULL, 'templates/standard/A8100-01.xlsx'),
  ('A8101-01', '비상사태 발생시 대응 방안', 'A-8101', '열람형 — 비상사태(화재·정전·재해) 발생 시 대응 절차·연락 체계·상황별 방안을 담은 책자형 참조 문서.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '6,8', NULL, NULL),
  ('A8101-02', '비상사태 대비 훈련결과 보고서', 'A-8101', '비상 대응 훈련을 실시한 뒤 쓰는 결과 보고서. 훈련 시나리오·참석 인원·소요 시간·문제점을 적습니다. 연 1회 이상 훈련 증거.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '6,8', NULL, 'templates/standard/A8101-02.xlsx'),
  ('A8101-03', '비상사태 대비 훈련 평가표', 'A-8101', '비상 대응 훈련의 평가표. 항목별 점수와 개선 필요 사항을 적습니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '6,8', NULL, 'templates/standard/A8101-03.xlsx'),
  ('A8101-04', '비상사태 검토 보고서', 'A-8101', '비상 대응 계획을 주기적으로 검토한 회의 기록. 연락망·장비·절차의 최신성을 확인합니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '6,8', NULL, 'templates/standard/A8101-04.xlsx'),
  ('B-2200', '지속적 개선업무 규정', 'B-2200', '「지속적 개선업무 규정」 규정 본문(열람용). 작성 양식이 아니며 본문은 문서관리에서 등록·개정합니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '10', NULL, NULL),
