  ('B1100-02', '부적합품 발생 통보서 관리대장', 'B-1100', '부적합품 발생 통보서의 발행 번호·일자·품번·처리 결과를 관리하는 대장.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, 'templates/standard/B1100-02.xlsx'),
  ('B1100-03', '특채 의뢰서', 'B-1100', '부적합품에 대한 특별 채용(특채) 의뢰. 고객 승인 필요 여부 포함.', '["작성","검토","승인"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, 'templates/standard/B1100-03.xlsx'),
  ('B1100-04', '수리 작업 일지', 'B-1100', '부적합품을 수리(리워크)한 작업 기록. 수리 방법·수량·재검사 결과를 적습니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, 'templates/standard/B1100-04.xlsx'),
