  ('B1100-07', '품질문제 발생 신속 대응 계통도', 'B-1100', '열람형 — 품질 문제 발생 시 보고·대응 순서를 그린 계통도와 신속대응 조직 연락망.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, NULL),
