  ('B1100-11', '부적합 보관장 관리 대장', 'B-1100', '부적합품 보관장(격리 구역)에 들어오고 나간 품목을 관리하는 대장. 격리 → 처리 결정까지의 흐름을 보여 줍니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, 'templates/standard/B1100-11.xlsx'),
  ('B1100-12', '리크·리워크 이력대장', 'B-1100', '기밀(리크) 불량의 발생부터 리워크·재검사·판정까지 추적하는 이력대장. 리워크 LOT에는 식별 표시(-R)를 붙입니다.', '[]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', '2_9,6_10', 'templates/standard/B1100-12.xlsx'),
