  ('B2100-08', '4M변경 내역 및 적용일자 관리', 'B-2100', '4M 변경 내역과 실제 적용일자를 관리하는 표. 변경 의뢰서와 번호로 연결됩니다.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '10', NULL, 'templates/standard/B2100-08.xlsx'),
